// Hardcoded India destinations dataset.
// All numbers are reasonable approximations curated for the demo.
// Costs are INR per person per day at "mid" travel style.

export type Interest =
  | "mountains"
  | "beach"
  | "heritage"
  | "spiritual"
  | "wildlife"
  | "adventure"
  | "desert"
  | "food"
  | "nightlife"
  | "backwaters";

export type Season = "winter" | "spring" | "summer" | "monsoon" | "autumn";

export interface Destination {
  id: string;
  name: string;
  state: string;
  region: "north" | "south" | "east" | "west" | "central" | "northeast";
  tagline: string;
  interests: Interest[];
  best_seasons: Season[];
  ideal_duration_days: [number, number]; // min, max
  cost_per_day_inr: number; // mid-range
  nearest_airport_iata: string;
  nearest_railhead: string;
  hero_image: string; // unsplash url
  highlights: string[];
  famous_food: string[];
  lat: number;
  lng: number;
  crowd_factor: number; // 0-1, higher = more touristy
  // Approx INR fare from major hub Delhi (DEL)
  approx_flight_inr_from_del: number;
  approx_train_inr_from_del: number;
}

